"""A thread-safe cache with a time to live, a loader callback, and optional bounds.

Every decision is taken under one lock (``self._cond``). The loader itself never runs under the lock, and
waiting for another thread's load is done on the condition variable, which releases the lock while it waits.
"""
import threading
import time
from collections import OrderedDict
from numbers import Real

from .stats import Stats


class DeadlockError(RuntimeError):
    """A ``get`` that would have completed a cycle of threads waiting for each other's loads."""


def _is_number(value):
    return isinstance(value, Real) and not isinstance(value, bool)


class _Load:
    """One load in flight, or a finished one that waiters may still hold."""

    __slots__ = ("owner", "done", "value", "error", "stale")

    def __init__(self, owner):
        self.owner = owner  # thread id of the thread running the loader
        self.done = False
        self.value = None
        self.error = None  # None means the load succeeded
        self.stale = None  # (value,) when a stale entry answers this failed load (guarantee 11)


class TTLCache:
    def __init__(self, loader, ttl, clock=time.monotonic, max_size=None, stale_grace=None):
        if not _is_number(ttl) or not ttl > 0:
            raise ValueError("ttl must be positive")
        if max_size is not None and (not isinstance(max_size, int) or isinstance(max_size, bool) or max_size < 1):
            raise ValueError("max_size must be None or an integer of at least 1")
        if stale_grace is not None and (not _is_number(stale_grace) or not stale_grace > 0):
            raise ValueError("stale_grace must be None or a number greater than zero")
        self._loader = loader
        self._ttl = ttl
        self._clock = clock
        self._max_size = max_size
        self._stale_grace = stale_grace
        self._cond = threading.Condition(threading.Lock())
        self._entries = OrderedDict()  # key -> (value, loaded_at); order is least recently used first
        self._inflight = {}  # key -> _Load, for loads that have not finished
        self._waiting = {}  # thread id -> _Load that thread is blocked on
        self._stats = Stats()

    def __len__(self):
        with self._cond:
            return len(self._entries)

    def get(self, key, timeout=None):
        if timeout is not None and not (_is_number(timeout) and timeout >= 0):
            raise ValueError("timeout must be None or a number of seconds, at least 0")
        me = threading.get_ident()
        with self._cond:
            now = self._clock()
            entry = self._entries.get(key)
            if entry is not None and now - entry[1] < self._ttl:
                self._entries.move_to_end(key)
                self._stats.hits += 1
                return entry[0]
            self._stats.misses += 1

            load = self._inflight.get(key)
            if load is None:
                load = _Load(me)
                self._inflight[key] = load
                self._stats.loads += 1
                run_loader = True
            else:
                run_loader = False
                if load.owner == me:
                    raise RuntimeError(f"get({key!r}) was called from inside the loader for that key")
                if self._completes_cycle(load, me):
                    self._stats.deadlocks += 1
                    raise DeadlockError(f"get({key!r}) would wait in a cycle of threads loading each other's keys")
                if timeout == 0:
                    self._stats.timeouts += 1
                    raise TimeoutError(f"load for {key!r} is still in flight")
                self._wait(load, me, timeout, key)
                return self._result(load)

        if not run_loader:  # pragma: no cover - the branches above always return or raise
            raise AssertionError("unreachable")
        return self._run_owner(key, load)

    def _run_owner(self, key, load):
        # The loader runs outside the lock, so other keys and other callers are never held up by it.
        try:
            value = self._loader(key)
            now = self._clock()
        except BaseException as exc:
            value, now, error = None, None, exc
        else:
            error = None
        with self._cond:
            try:
                load.value = value
                load.error = error
                if error is None:
                    self._entries[key] = (value, now)
                    self._entries.move_to_end(key)
                    self._evict()
                else:
                    self._stats.failures += 1
                    if isinstance(error, Exception):
                        load.stale = self._stale_entry(key, self._clock())
            finally:
                del self._inflight[key]
                load.done = True
                self._cond.notify_all()
            return self._result(load)

    def _result(self, load):
        """What a call receives for a finished load. Must be called with the lock held."""
        if load.error is None:
            return load.value
        if load.stale is not None:
            self._stats.stale_served += 1
            return load.stale[0]
        raise load.error

    def _wait(self, load, me, timeout, key):
        """Block until ``load`` is done. Must be called with the lock held."""
        self._waiting[me] = load
        try:
            deadline = None if timeout is None else time.monotonic() + timeout
            while not load.done:
                if deadline is None:
                    self._cond.wait()
                    continue
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    self._stats.timeouts += 1
                    raise TimeoutError(f"timed out waiting for the load of {key!r}")
                self._cond.wait(remaining)
        finally:
            self._waiting.pop(me, None)

    def _completes_cycle(self, load, me):
        """True if waiting for ``load`` closes a cycle of threads that wait for each other. Lock held."""
        seen = set()
        thread = load.owner
        while True:
            if thread == me:
                return True
            if thread in seen:
                return False
            seen.add(thread)
            blocked_on = self._waiting.get(thread)
            if blocked_on is None or blocked_on.done:
                return False
            thread = blocked_on.owner

    def _stale_entry(self, key, now):
        """``(value,)`` if the stored entry for ``key`` is stale at ``now``, else None. Lock held."""
        entry = self._entries.get(key)
        if self._stale_grace is None or entry is None:
            return None
        age = now - entry[1]
        if self._ttl <= age < self._ttl + self._stale_grace:
            return (entry[0],)
        return None

